// A deputy: granted fs:read, it reads whatever path a caller hands it — including
// when it is DETACHED from the caller's frame and driven as a promise reaction
// (`Promise.resolve(x).then(deputy.readFor)`). Under schedule-time attribution
// the scheduling principal is recovered into the deputy-class stack AND, so the
// deputy still reads for a granted scheduler but not for an ungranted one.
// @ref LLP 0013#phase-5
var fs = require("fs");
module.exports.readFor = function readFor(path) {
  return String(fs.readFileSync(path)).trim();
};
